INSERT INTO monsters ("Name", "Description", "ImagePath") VALUES
($$Кибер Киса$$, $$Быстрый робот с большим запасом энергии и ловкими атаками. Отлично уворачивается и первым захватывает Токио.$$, $$/assets/images/ph_monster_kitty.svg$$),
($$Гигазавр$$, $$Мощный монстр, который любит разрушать город и давить соперников. Выигрывает за счёт грубой силы и высокого здоровья.$$, $$/assets/images/ph_monster_dino.svg$$),
($$Космо пингвин$$, $$Необычный герой с замороженными атаками и хитрой тактикой. Замораживает соперников и копит энергию.$$, $$/assets/images/ph_monster_penguin.svg$$);
INSERT INTO cards ("Name", "Type", "Description", "ImagePath") VALUES
($$Стимул для аутсайдера$$, $$Вспомогательная$$, $$Если в конце хода у вас меньше всех очков, получите 1 очко.$$, $$/assets/images/ph_helper_drink.svg$$),
($$Бомбардировка$$, $$Вспомогательная$$, $$Все монстры (включая вас) теряют по 3 здоровья.$$, $$/assets/images/ph_helper_shield.svg$$),
($$Искусственный отбор$$, $$Вспомогательная$$, $$Вы можете изменять один из кубиков на 1 каждый ход.$$, $$/assets/images/ph_helper_strike.svg$$),
($$Имитация$$, $$Особая$$, $$Выберите карту Оставьте, которая принадлежит любому монстру, и поместите на нее жетон имитации. Карта «Имитация» считается копией этой карты.$$, $$/assets/images/ph_helper_drink.svg$$),
($$Метаморф$$, $$Особая$$, $$В конце вашего хода вы можете сбросить любые ваши карты Оставьте и получить энергию в количестве, равном их полной цене.$$, $$/assets/images/ph_helper_shield.svg$$),
($$Ядовитая слюна$$, $$Особая$$, $$Поместите 1 жетон яда на планшет каждого монстра, которого атакуете с помощью кубика атаки. В конце своего хода монстр теряет 1 здоровье за каждый жетон яда на нем.$$, $$/assets/images/ph_helper_strike.svg$$);
INSERT INTO items ("Name", "Category", "Description", "ImagePath", "Quantity") VALUES
($$Черные кубики$$, $$Кубики$$, $$Шесть шестигранных кубиков с символами: числа, сердца, молнии и когти.$$, $$/assets/images/ph_comp_dice.svg$$, 6),
($$Игровое поле$$, $$Поле$$, $$Поле с зонами города. Кто стоит в Токио — получает очки и атакует всех снаружи.$$, $$/assets/images/ph_comp_board.svg$$, 1),
($$Кубы энергии$$, $$Жетоны$$, $$Накопленная энергия тратится на покупку вспомогательных карт.$$, $$/assets/images/ph_comp_energy.svg$$, 50),
($$Планшеты монстров$$, $$Планшеты$$, $$Трекер здоровья и очков каждого монстра. Если набрать 20 очков — это победа, но если здоровье падает до 0 — монстр выбывает.$$, $$/assets/images/ph_comp_health.svg$$, 6),
($$Жетоны$$, $$Жетоны$$, $$Используются при активации вспомогательной карты.$$, $$/assets/images/ph_comp_figures.svg$$, 28),
($$Зеленые кубики$$, $$Кубики$$, $$Два шестигранных кубика с символами: числа, сердца, молнии и когти. Используются при активации вспомогательной карты.$$, $$/assets/images/ph_comp_deck.svg$$, 2);
INSERT INTO rules ("Slug", "Title", "Content", "SortOrder") VALUES
($$cel-igry$$, $$Цель игры$$, $$<section class="win-cards"><div class="panel win-card"><div class="win-icon">⭐</div><h3>Победа по очкам</h3><p>Первым набери <strong>20 победных очков</strong> — и ты Повелитель Токио.</p></div><div class="panel win-card"><div class="win-icon">💀</div><h3>Победа уничтожением</h3><p>Устрани всех соперников и стань <strong>последним выжившим</strong> монстром.</p></div></section><p class="small">Здоровье каждого монстра — 10 очков (по умолчанию). Если здоровье падает до 0, монстр выбывает.</p>$$, 1),
($$podgotovka$$, $$Подготовка$$, $$<section class="step-cards"><div class="panel step-card"><span class="step-num">1</span><p>Каждый игрок выбирает карточку монстра и получает соответствующую фигурку.</p></div><div class="panel step-card"><span class="step-num">2</span><p>Все начинают вне Токио с 10 очками здоровья и 0 победных очков.</p></div><div class="panel step-card"><span class="step-num">3</span><p>Положи 6 кубиков, жетоны энергии и колоду карт в центр стола.</p></div><div class="panel step-card"><span class="step-num">4</span><p>Выложи 3 карты предметов лицом вверх — их можно будет купить.</p></div><div class="panel step-card"><span class="step-num">5</span><p>Каждый игрок бросает 6 кубиков. Тот, у кого выпало больше всего Атаки, ходит первым.</p></div></section>$$, 2),
($$hod-igry$$, $$Ход игры$$, $$<section class="flow"><div class="flow-step"><div class="flow-num">1</div><h3>Бросок</h3><p class="small">Брось 6 кубиков.</p></div><div class="flow-arrow">→</div><div class="flow-step"><div class="flow-num">2</div><h3>Переброс</h3><p class="small">Перебрось ненужные до трёх раз.</p></div><div class="flow-arrow">→</div><div class="flow-step"><div class="flow-num">3</div><h3>Применить</h3><p class="small">Считай результат и купи карты.</p></div></section><p class="small">После финального броска применяются результаты: числа дают очки, сердца лечат, молнии дают энергию, когти атакуют. Затем можно купить карты за энергию — и ход переходит дальше.</p>$$, 3),
($$grani-kubika$$, $$Грани кубика$$, $$<section class="dice-grid"><div class="dice"><span class="face">1</span><p class="small">Три единицы = 1 очко, четыре = 2 и т.д.</p></div><div class="dice"><span class="face">2</span><p class="small">Три двойки = 2 очка, четыре = 3 и т.д.</p></div><div class="dice"><span class="face">3</span><p class="small">Три тройки = 3 очка, четыре = 4 и т.д.</p></div><div class="dice"><span class="face">❤️</span><p class="small">Сердце — +1 здоровье (вне Токио).</p></div><div class="dice"><span class="face">⚡</span><p class="small">Молния — +1 жетон энергии.</p></div><div class="dice"><span class="face">🐾</span><p class="small">Коготь — атака на 1 урон.</p></div></section><p class="small">Очки за числа засчитываются только за три и более одинаковых значения. Сердца не лечат, когда монстр находится внутри Токио.</p>$$, 4),
($$tokyo$$, $$Токио$$, $$<section class="tokyo-diagram"><div class="tokyo-out">👾<br><strong>Монстры<br>вне Токио</strong></div><div class="tokyo-center"><strong>ТОКИО</strong><p class="small" style="color:#ebe6f2;">+1 очко в начале хода<br>+1 за вступление</p></div><div class="tokyo-out">👾<br><strong>Монстры<br>вне Токио</strong></div></section><ul class="goal-list" style="margin-top:14px"><li><strong>Монстр в Токио</strong> бьёт когтями всех монстров вне Токио.</li><li><strong>Монстры вне Токио</strong> бьют когтями только того, кто стоит в городе.</li><li>Если монстр в Токио получает урон, он может <strong>уступить город</strong> — тогда атаковавший занимает его место.</li></ul>$$, 5),
($$karty-i-energiya$$, $$Карты и энергия$$, $$<p>Молнии дают жетоны энергии. Энергия тратится на покупку карт из трёх открытых на столе. Купленная карта бывает трёх видов:</p><section class="card-types"><div class="panel card-type"><div class="feature-icon">📌</div><h3>Держится</h3><p class="small">Остаётся у игрока и даёт постоянный бонус.</p></div><div class="panel card-type"><div class="feature-icon">💥</div><h3>Срабатывает</h3><p class="small">Применяется один раз и сбрасывается.</p></div><div class="panel card-type"><div class="feature-icon">✨</div><h3>Особая</h3><p class="small">Выполняет уникальное действие по описанию.</p></div></section><p class="small">После покупки карты на её место выкладывается новая из колоды. Список карт — на странице <a href="/card/index">Карты</a>.</p>$$, 6),
($$pobeda$$, $$Победа$$, $$<section class="rules-banner victory-banner"><div class="banner-stats"><div class="banner-stat"><span class="banner-num">20</span><span>победных очков</span></div><div class="banner-stat"><span class="banner-num">1</span><span>выживший монстр</span></div></div><p class="banner-goal">Игра заканчивается сразу, как только кто-то набирает 20 очков или остаётся последним выжившим.</p><p class="small" style="text-align:center;color:#fff">При одновременной победе нескольких игроков — выигрывает тот, у кого больше очков; при равенстве — больше энергии; при полном равенстве победа делится.</p></section>$$, 7);
INSERT INTO strategies ("Slug", "Title", "Content", "Category") VALUES
($$dva-puti$$, $$Два пути к победе$$, $$<section class="win-cards"><div class="panel win-card"><div class="win-icon">⭐</div><h3>Идти в очки</h3><p>Копи числа на кубиках и задерживайся в Токио ради +1 очка за ход. Подходит, когда соперники пассивны и редко атакуют.</p></div><div class="panel win-card"><div class="win-icon">💀</div><h3>Идти в атаку</h3><p>Собирай когти и выбивай соперников по одному. Подходит, когда у тебя сильный монстр и слабые соседи.</p></div></section><p class="small">Лучше всего — держать оба пути открытыми и переключаться в зависимости от ситуации за столом.</p>$$, $$Общая$$),
($$klyuchevye-strategii$$, $$Ключевые стратегии$$, $$<section class="cards"><article class="card"><div class="card-body"><h3>Когда входить в Токио</h3><p class="small">Входи, когда у тебя много здоровья (от 7). В городе ты получаешь +1 очко за ход и +1 за вступление, но тебя бьют все снаружи. Не входи с низким здоровьем — быстро собьют.</p></div></article><article class="card"><div class="card-body"><h3>Когда уходить из Токио</h3><p class="small">Уходи, когда здоровье падает ниже 5 и нет сердец для лечения. Уступить город можно после атаки — делай это, чтобы выжить и вернуться позже.</p></div></article><article class="card"><div class="card-body"><h3>Выбор граней</h3><p class="small">В защите оставляй сердца и молнии; в атаке — когти и числа. Три одинаковых числа сразу дают очки, поэтому не разбрасывайся значениями.</p></div></article><article class="card"><div class="card-body"><h3>Покупка карт</h3><p class="small">Приоритет — карты постоянной защиты и дополнительного здоровья. Карты разового эффекта бери только в решающий момент, а не про запас.</p></div></article><article class="card"><div class="card-body"><h3>Копи энергию рано</h3><p class="small">В первых ходах собирай молнии и покупай дешёвые карты-бонусы. Дешёвая защита в начале окупается всю партию.</p></div></article><article class="card"><div class="card-body"><h3>Следи за соперниками</h3><p class="small">Если у кого-то много энергии — он скоро купит сильную карту, бей его первым. Если кто-то копит очки — атакуй, не давай ему уйти в отрыв.</p></div></article></section>$$, $$Общая$$),
($$fazy-partii$$, $$Тактика по фазам партии$$, $$<section class="step-cards"><div class="panel step-card"><span class="step-num">1</span><p><strong>Начало.</strong> Копи энергию и здоровье, не лезь в драку. Купи 1–2 дешёвые карты.</p></div><div class="panel step-card"><span class="step-num">2</span><p><strong>Середина.</strong> Займи Токио на 2–3 хода, набери очки, затем уступи и полечись.</p></div><div class="panel step-card"><span class="step-num">3</span><p><strong>Конец.</strong> Если близок к 20 очкам — рви к финишу. Если нет — добивай ослабших.</p></div></section>$$, $$Общая$$),
($$opasnye-oshibki$$, $$Опасные ошибки$$, $$<ul class="goal-list"><li>❌ <strong>Вставать в Токио с 1 HP</strong> — даже ради очков. Тебя собьют до следующего хода.</li><li>❌ <strong>Гнаться за картами и забывать про здоровье</strong> — энергия не спасёт от когтей.</li><li>❌ <strong>Держаться за Токио до последнего</strong> — лучше уступить и вернуться, чем погибнуть.</li><li>❌ <strong>Игнорировать лидера по очкам</strong> — если кто-то близок к 20, атакуй его в первую очередь.</li></ul><section class="rules-banner" style="margin-top:24px"><p class="banner-goal">Главное правило: <strong>гибкость</strong>. Нет одной выигрышной стратегии — побеждает тот, кто быстрее всех перестраивается под ситуацию за столом.</p></section>$$, $$Защита$$);
